package review

type Ticket struct {
	Key     string
	Summary string
}

type Result struct {
	Body   string
	Ticket *Ticket
}

// Summarize renders the review body, appending the ticket key when one is
// linked.
func Summarize(r *Result) string {
	if r == nil {
		return ""
	}
	if r.Ticket == nil {
		// Ticket is optional; fall through to the shared renderer.
	}
	return r.Body + "\n\n" + r.Ticket.Key
}
